package cn.zhuatech.legalai.controller; import cn.zhuatech.legalai.common.ApiResponse; import cn.zhuatech.legalai.service.ContractReviewService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/ai") @PreAuthorize("hasAnyRole('DOMAIN_USER','DOMAIN_OPERATOR','ADMIN')") public class AiFeatureController { private final ContractReviewService service; public AiFeatureController(ContractReviewService service){this.service=service;} @PostMapping("/contract/review") public ApiResponse<ContractReviewService.Result> execute(@Valid @RequestBody ContractReviewService.Request request){return ApiResponse.ok("合同条款风险预审完成",service.review(request));} }